(1166, 'isotonic drink (light-coloured)', 'can', 'Water and specified clear/light-coloured drinks are directly permitted during clear-liquid phases, subject to hospital timing and colour rules. Modification: Only while clear fluids are permitted; stop at the hospital-specific fasting cut-off. Common ambiguity: Colour restrictions vary; avoid red/blue/purple where instructed.', 'DIETICIAN', 'Consolidated baseline — Sengkang General Hospital — Diet Advice (https://www.skh.com.sg/ward-stay/admissions/preparing-for-colonoscopy/diet-advice); National University Hospital — Preparing for Your Colonoscopy booklet (https://www.nuh.com.sg/docs/nuhlibraries/brochures-document/colonoscopy-colonoscopy-preparation_peb_eng_a5_v2_fa.pdf)', '2026-09-16T17:33:24.724092+00:00'),
(1167, 'isotonic drink (red/purple/blue)', 'cannot', 'SKH excludes dark/red liquids such as grape, prune and tomato juice; colour restrictions also appear in NUH paediatric clear-fluid guidance. Modification: Avoid during the stated phase unless your hospital explicitly instructs otherwise.', 'DIETICIAN', 'Consolidated baseline — Sengkang General Hospital — Diet Advice (https://www.skh.com.sg/ward-stay/admissions/preparing-for-colonoscopy/diet-advice); National University Hospital — Paediatric colonoscopy food and drinks diet (https://www.nuh.com.sg/docs/nuhlibraries/content-document/care-at-nuh/specialties/paediatrics/150421_nuh-a5-colonoscopy-booklet-lowres-preview-%281%29.pdf?sfvrsn=10781797_1)', '2026-09-16T17:33:24.724092+00:00'),
(1168, 'bandung', 'review', 'NUH and SKH avoid milk/milk products, while TTSH permits coffee/tea with or without milk during its 3-day low-fibre phase. Modification: Check the exact hospital protocol; do not infer permission from fibre content alone. Common ambiguity: Milk-based and coloured. Hospital sheets conflict — follow your own hospital''s form. Pending clinical review. Is milk/dairy prohibited throughout the low-residue phase under the target protocol, or only once clear liquids are required?', 'DIETICIAN', 'Consolidated baseline — Sengkang General Hospital — Diet Advice (https://www.skh.com.sg/ward-stay/admissions/preparing-for-colonoscopy/diet-advice); National University Hospital — Preparing for Your Colonoscopy booklet (https://www.nuh.com.sg/docs/nuhlibraries/brochures-document/colonoscopy-colonoscopy-preparation_peb_eng_a5_v2_fa.pdf); National University Hospital — Colorectal Cancer / bowel preparation guidance (https://www.nuh.com.sg/health-resources/diseases-and-conditions/colorectal-cancer); Tan Tock Seng Hospital — Preparing for a Colonoscopy (PEG patient guide) (https://www.ttsh.com.sg/Patients-and-Visitors/Documents/Preparing%20for%20a%20Colonoscopy%20-%20For%20Patients%20Prescribed%20with%202L%20or%203L%20PEG%20%288AM%20to%202PM%29.pdf)', '2026-09-16T17:33:24.724092+00:00'),
(1169, 'soy bean drink', 'review', 'NUH and SKH avoid milk/milk products, while TTSH permits coffee/tea with or without milk during its 3-day low-fibre phase. Modification: Check the exact hospital protocol; do not infer permission from fibre content alone. Hospital sheets conflict — follow your own hospital''s form. Pending clinical review. Is milk/dairy prohibited throughout the low-residue phase under the target protocol, or only once clear liquids are required?', 'DIETICIAN', 'Consolidated baseline — Sengkang General Hospital — Diet Advice (https://www.skh.com.sg/ward-stay/admissions/preparing-for-colonoscopy/diet-advice); National University Hospital — Preparing for Your Colonoscopy booklet (https://www.nuh.com.sg/docs/nuhlibraries/brochures-document/colonoscopy-colonoscopy-preparation_peb_eng_a5_v2_fa.pdf); National University Hospital — Colorectal Cancer / bowel preparation guidance (https://www.nuh.com.sg/health-resources/diseases-and-conditions/colorectal-cancer); Tan Tock Seng Hospital — Preparing for a Colonoscopy (PEG patient guide) (https://www.ttsh.com.sg/Patients-and-Visitors/Documents/Preparing%20for%20a%20Colonoscopy%20-%20For%20Patients%20Prescribed%20with%202L%20or%203L%20PEG%20%288AM%20to%202PM%29.pdf)', '2026-09-16T17:33:24.724092+00:00'),
(1170, 'chin chow drink', 'cannot', 'NUH adult guidance explicitly lists jelly and agar-agar among foods to avoid; paediatric NUH also avoids gelatine desserts during clear fluids. Modification: Avoid during the stated phase unless your hospital explicitly instructs otherwise. Common ambiguity: Contains grass jelly solids unless fully removed; not a clear liquid.', 'DIETICIAN', 'Consolidated baseline — National University Hospital — Preparing for Your Colonoscopy booklet (https://www.nuh.com.sg/docs/nuhlibraries/brochures-document/colonoscopy-colonoscopy-preparation_peb_eng_a5_v2_fa.pdf); National University Hospital — Outpatient Consultation / Bowel Cleansing (https://www.nuh.com.sg/care-at-nuh/outpatient-consation); National University Hospital — Paediatric colonoscopy food and drinks diet (https://www.nuh.com.sg/docs/nuhlibraries/content-document/care-at-nuh/specialties/paediatrics/150421_nuh-a5-colonoscopy-booklet-lowres-preview-%281%29.pdf?sfvrsn=10781797_1)', '2026-09-16T17:33:24.724092+00:00'),
(1171, 'jelly', 'cannot', 'NUH adult guidance explicitly lists jelly and agar-agar among foods to avoid; paediatric NUH also avoids gelatine desserts during clear fluids. Modification: Avoid during the stated phase unless your hospital explicitly instructs otherwise.', 'DIETICIAN', 'Consolidated baseline — National University Hospital — Preparing for Your Colonoscopy booklet (https://www.nuh.com.sg/docs/nuhlibraries/brochures-document/colonoscopy-colonoscopy-preparation_peb_eng_a5_v2_fa.pdf); National University Hospital — Outpatient Consultation / Bowel Cleansing (https://www.nuh.com.sg/care-at-nuh/outpatient-consation); National University Hospital — Paediatric colonoscopy food and drinks diet (https://www.nuh.com.sg/docs/nuhlibraries/content-document/care-at-nuh/specialties/paediatrics/150421_nuh-a5-colonoscopy-booklet-lowres-preview-%281%29.pdf?sfvrsn=10781797_1)', '2026-09-16T17:33:24.724092+00:00'),
(1172, 'agar-agar', 'cannot', 'NUH adult guidance explicitly lists jelly and agar-agar among foods to avoid; paediatric NUH also avoids gelatine desserts during clear fluids. Modification: Avoid during the stated phase unless your hospital explicitly instructs otherwise.', 'DIETICIAN', 'Consolidated baseline — National University Hospital — Preparing for Your Colonoscopy booklet (https://www.nuh.com.sg/docs/nuhlibraries/brochures-document/colonoscopy-colonoscopy-preparation_peb_eng_a5_v2_fa.pdf); National University Hospital — Outpatient Consultation / Bowel Cleansing (https://www.nuh.com.sg/care-at-nuh/outpatient-consation); National University Hospital — Paediatric colonoscopy food and drinks diet (https://www.nuh.com.sg/docs/nuhlibraries/content-document/care-at-nuh/specialties/paediatrics/150421_nuh-a5-colonoscopy-booklet-lowres-preview-%281%29.pdf?sfvrsn=10781797_1)', '2026-09-16T17:33:24.724092+00:00');
